    {
      "@type": "Question",
      "name": "Does a CE mark allow sale in Saudi Arabia?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. The Saudi Food and Drug Authority operates its own approval process. Approval elsewhere may support an application but does not replace it."
      }
    },
    {
      "@type": "Question",
      "name": "Who is responsible for SFDA registration?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The party placing the product on the Saudi market, not the factory that made it. A manufacturer can supply a fully compliant device and still leave the importer holding a registration problem."
      }
    },
    {
      "@type": "Question",
      "name": "When should registration requirements be established?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Before a supplier is selected. Buyers who commit to a supplier and agree a price first lose the leverage to change supplier when the certification turns out not to support registration."
      }
    }
  ]
